insert into public.quotes (text_ru, text_en, author, category) values
  ('Лучший способ начать — перестать говорить и начать делать.', 'The best way to get started is to quit talking and begin doing.', 'Уолт Дисней', 'motivation'),
  ('Не позволяй вчерашнему дню занимать слишком много места в сегодняшнем.', 'Don''t let yesterday take up too much of today.', 'Уилл Роджерс', 'motivation'),
  ('Важно не то, что ты упал, а то, что ты встал.', 'It''s not whether you get knocked down, it''s whether you get up.', 'Винс Ломбарди', 'motivation'),
  ('Успех — это не финал, провал — не смерть: важно лишь мужество продолжать.', 'Success is not final, failure is not fatal: it is the courage to continue that counts.', 'Уинстон Черчилль', 'motivation'),
  ('Верь, что можешь — и ты уже на полпути.', 'Believe you can and you''re halfway there.', 'Теодор Рузвельт', 'motivation'),
  ('Ваше время ограничено, не тратьте его на чужую жизнь.', 'Your time is limited, so don''t waste it living someone else''s life.', 'Стив Джобс', 'motivation'),
  ('Единственный предел тому, что мы осуществим завтра, — наши сомнения сегодня.', 'The only limit to our realization of tomorrow will be our doubts of today.', 'Франклин Рузвельт', 'motivation'),
  ('Всё кажется невозможным, пока не будет сделано.', 'It always seems impossible until it''s done.', 'Нельсон Мандела', 'motivation'),
  ('Делай то, что можешь, с тем, что имеешь, там, где ты есть.', 'Do what you can, with what you have, where you are.', 'Теодор Рузвельт', 'motivation'),
  ('Всё, чего ты хочешь, находится по другую сторону страха.', 'Everything you''ve ever wanted is on the other side of fear.', 'Джордж Аддэр', 'motivation'),
  ('Начни там, где стоишь. Используй то, что есть. Делай, что можешь.', 'Start where you are. Use what you have. Do what you can.', 'Артур Эш', 'motivation'),
  ('Упади семь раз, встань восемь.', 'Fall seven times and stand up eight.', 'Японская пословица', 'motivation'),
  ('Путь в тысячу ли начинается с первого шага.', 'A journey of a thousand miles begins with a single step.', 'Лао-цзы', 'motivation'),
  ('Веди себя так, будто то, что ты делаешь, имеет значение. Оно имеет.', 'Act as if what you do makes a difference. It does.', 'Уильям Джеймс', 'motivation'),
  ('Качество — это не поступок, а привычка.', 'Quality is not an act, it is a habit.', 'Аристотель', 'motivation'),
  ('Секрет того, чтобы двигаться вперёд, — начать.', 'The secret of getting ahead is getting started.', 'Марк Твен', 'motivation'),
  ('Сделанное лучше сказанного.', 'Well done is better than well said.', 'Бенджамин Франклин', 'motivation'),
  ('Ты упускаешь 100% бросков, которые не делаешь.', 'You miss 100% of the shots you don''t take.', 'Уэйн Гретцки', 'motivation'),
  ('Думаешь, можешь, или думаешь, что не можешь — ты в обоих случаях прав.', 'Whether you think you can or you think you can''t, you''re right.', 'Генри Форд', 'motivation'),
  ('Я не терпел неудач. Я просто нашёл 10 000 способов, которые не работают.', 'I have not failed. I''ve just found 10,000 ways that won''t work.', 'Томас Эдисон', 'motivation'),
  ('Важнее не то, что ты получишь, достигнув цели, а то, кем станешь.', 'What you get by achieving your goals is not as important as what you become.', 'Зиг Зиглар', 'motivation'),
  ('Мотивация даёт старт, но дисциплина обеспечивает рост.', 'Motivation gets you going, but discipline keeps you growing.', 'Джон Максвелл', 'motivation'),
  ('Будущее зависит от того, что ты делаешь сегодня.', 'The future depends on what you do today.', 'Махатма Ганди', 'motivation'),
  ('Трудности готовят обычных людей к необычной судьбе.', 'Hardships often prepare ordinary people for an extraordinary destiny.', 'Клайв Льюис', 'motivation'),
  ('Если ты работаешь над чем-то вдохновляющим, это будет держать тебя мотивированным.', 'If you are working on something exciting, it will keep you motivated.', 'Стив Джобс', 'motivation'),
  ('Мы — то, что мы делаем постоянно. Совершенство — не действие, а привычка.', 'We are what we repeatedly do. Excellence, then, is not an act but a habit.', 'Аристотель', 'discipline'),
  ('Дисциплина — это мост между целями и их достижением.', 'Discipline is the bridge between goals and accomplishment.', 'Джим Рон', 'discipline'),
  ('Мотивация даёт старт. Привычка позволяет продолжать.', 'Motivation is what gets you started. Habit is what keeps you going.', 'Джим Райан', 'discipline'),
  ('Разница между успешным человеком и другими — не нехватка силы, а нехватка воли.', 'The difference between a successful person and others is not a lack of strength, but rather a lack of will.', 'Винс Ломбарди', 'discipline'),
  ('Сначала мы формируем привычки, потом они формируют нас.', 'First we form habits, then they form us.', 'Роб Гилберт', 'discipline'),
  ('Маленькие дисциплины, повторяемые ежедневно, ведут к большим достижениям.', 'Small disciplines repeated with consistency lead to great achievements.', 'Джон Максвелл', 'discipline'),
  ('Победивший самого себя — сильнейший воин.', 'He who conquers himself is the mightiest warrior.', 'Конфуций', 'discipline'),
  ('Управляй своим разумом, иначе он управит тобой.', 'Rule your mind or it will rule you.', 'Гораций', 'discipline'),
  ('Не свободен тот, кто не владеет собой.', 'No man is free who is not master of himself.', 'Эпиктет', 'discipline'),
  ('Все мы страдаем от одной из двух болей: боли дисциплины или боли сожаления.', 'We must all suffer from one of two pains: the pain of discipline or the pain of regret.', 'Джим Рон', 'discipline'),
  ('Дисциплина — это выбор между тем, чего ты хочешь сейчас, и тем, чего хочешь больше всего.', 'Discipline is choosing between what you want now and what you want most.', 'Августа Кантра', 'discipline'),
  ('Успех — это несколько простых дисциплин, практикуемых каждый день.', 'Success is nothing more than a few simple disciplines practiced every day.', 'Джим Рон', 'discipline'),
  ('Дело не в том, что я такой умный, — я просто подольше задерживаюсь с проблемами.', 'It''s not that I''m so smart, it''s just that I stay with problems longer.', 'Альберт Эйнштейн', 'discipline'),
  ('Гений — это один процент вдохновения и девяносто девять пота.', 'Genius is one percent inspiration and ninety-nine percent perspiration.', 'Томас Эдисон', 'discipline'),
  ('Желание победить ничего не значит без желания готовиться.', 'The will to win means nothing without the will to prepare.', 'Джума Иканга', 'discipline'),
  ('Через год ты можешь пожалеть, что не начал сегодня.', 'A year from now you may wish you had started today.', 'Карен Лэмб', 'discipline'),
  ('Не следи за часами — делай, что делает она: продолжай.', 'Don''t watch the clock; do what it does. Keep going.', 'Сэм Левенсон', 'discipline'),
  ('Упорство — не длинная гонка, а много коротких, одна за другой.', 'Perseverance is not a long race; it is many short races one after the other.', 'Уолтер Эллиот', 'discipline'),
  ('Либо ты управляешь днём, либо день управляет тобой.', 'Either you run the day or the day runs you.', 'Джим Рон', 'discipline'),
  ('Когда есть решимость, нужны дисциплина и тяжёлый труд, чтобы дойти.', 'Once you have commitment, you need the discipline and hard work to get you there.', 'Хайле Гебреселассие', 'discipline'),
  ('Самообладание — главная из дисциплин.', 'Self-command is the main discipline.', 'Ральф Эмерсон', 'discipline'),
  ('У тебя есть власть над своим разумом, а не над внешними событиями. Осознай это — и обретёшь силу.', 'You have power over your mind — not outside events. Realize this, and you will find strength.', 'Марк Аврелий', 'discipline'),
  ('То, как мы проводим дни, — это и есть то, как мы проводим жизнь.', 'How we spend our days is, of course, how we spend our lives.', 'Энни Диллард', 'discipline'),
  ('То, что мы делаем каждый день, важнее того, что мы делаем время от времени.', 'What we do every day matters more than what we do once in a while.', 'Гретхен Рубин', 'discipline'),
  ('Сила воли — это мышца. Тренируй её каждый день.', 'Willpower is a muscle. Train it every day.', 'Народная мудрость', 'discipline'),
  ('Где есть любовь, там есть жизнь.', 'Where there is love there is life.', 'Махатма Ганди', 'love'),
  ('Любовь — это одна душа, живущая в двух телах.', 'Love is composed of a single soul inhabiting two bodies.', 'Аристотель', 'love'),
  ('Лучшая опора в жизни — друг на друге.', 'The best thing to hold onto in life is each other.', 'Одри Хепбёрн', 'love'),
  ('Любовь не признаёт преград.', 'Love recognizes no barriers.', 'Майя Анджелоу', 'love'),
  ('Любить и быть любимым — значит чувствовать солнце с обеих сторон.', 'To love and be loved is to feel the sun from both sides.', 'Дэвид Вискотт', 'love'),
  ('Мы наиболее живы, когда любим.', 'We are most alive when we are in love.', 'Джон Апдайк', 'love'),
  ('У сердца свои причины, о которых разум ничего не знает.', 'The heart has its reasons of which reason knows nothing.', 'Блез Паскаль', 'love'),
  ('Быть глубоко любимым — это сила, а глубоко любить — это смелость.', 'Being deeply loved by someone gives you strength, while loving someone deeply gives you courage.', 'Лао-цзы', 'love'),
  ('Любовь — это дружба, положенная на музыку.', 'Love is a friendship set to music.', 'Джозеф Кэмпбелл', 'love'),
  ('Если я знаю, что такое любовь, то благодаря тебе.', 'If I know what love is, it is because of you.', 'Герман Гессе', 'love'),
  ('Дарить любовь — само по себе урок.', 'The giving of love is an education in itself.', 'Элеонора Рузвельт', 'love'),
  ('Любовь исцеляет — и тех, кто дарит, и тех, кто принимает.', 'Love cures people — both the ones who give it and the ones who receive it.', 'Карл Меннингер', 'love'),
  ('Любящее сердце — истинная мудрость.', 'A loving heart is the truest wisdom.', 'Чарльз Диккенс', 'love'),
  ('Любовь не властвует, она взращивает.', 'Love does not dominate; it cultivates.', 'Иоганн Гёте', 'love'),
  ('Единственное счастье в жизни — любить и быть любимым.', 'There is only one happiness in this life, to love and be loved.', 'Жорж Санд', 'love'),
  ('Жизнь — это цветок, а любовь — его мёд.', 'Life is the flower for which love is the honey.', 'Виктор Гюго', 'love'),
  ('Люби всех, доверяй немногим, не делай зла никому.', 'Love all, trust a few, do wrong to none.', 'Уильям Шекспир', 'love'),
  ('Величайшее счастье жизни — уверенность в том, что тебя любят.', 'The greatest happiness of life is the conviction that we are loved.', 'Виктор Гюго', 'love'),
  ('Любовь — это когда счастье другого важнее твоего.', 'Love is when the other person''s happiness is more important than your own.', 'Джексон Браун', 'love'),
  ('От прикосновения любви каждый становится поэтом.', 'At the touch of love everyone becomes a poet.', 'Платон', 'love'),
  ('Любовь — это неудержимое желание быть неудержимо желанным.', 'Love is an irresistible desire to be irresistibly desired.', 'Роберт Фрост', 'love'),
  ('В конце концов, любовь, которую ты берёшь, равна любви, которую ты отдаёшь.', 'In the end, the love you take is equal to the love you make.', 'Пол Маккартни', 'love'),
  ('Любить себя — начало романа длиною в жизнь.', 'To love oneself is the beginning of a lifelong romance.', 'Оскар Уайльд', 'love'),
  ('Доброта — язык, который слышат глухие и видят слепые.', 'Kindness is a language which the deaf can hear and the blind can see.', 'Марк Твен', 'love'),
  ('Любовь — единственное сокровище, которое растёт, когда его тратишь.', 'Love is the one treasure that grows when you spend it.', 'Рита Браун', 'love'),
  ('Никто не сможет заставить тебя чувствовать себя хуже без твоего согласия.', 'No one can make you feel inferior without your consent.', 'Элеонора Рузвельт', 'confidence'),
  ('С уверенностью ты победил ещё до старта.', 'With confidence, you have won before you have started.', 'Маркус Гарви', 'confidence'),
  ('Верь в себя и во всё, что ты есть.', 'Believe in yourself and all that you are.', 'Кристиан Ларсон', 'confidence'),
  ('Ты сам заслуживаешь своей любви и привязанности не меньше, чем кто-либо.', 'You yourself, as much as anybody in the entire universe, deserve your love and affection.', 'Приписывается Будде', 'confidence'),
  ('Оптимизм — это вера, ведущая к достижению.', 'Optimism is the faith that leads to achievement.', 'Хелен Келлер', 'confidence'),
  ('Мы покоряем не гору, а себя.', 'It is not the mountain we conquer but ourselves.', 'Эдмунд Хиллари', 'confidence'),
  ('Сомнения убивают больше мечтаний, чем неудачи.', 'Doubt kills more dreams than failure ever will.', 'Сьюзи Кассем', 'confidence'),
  ('Смелость — это не отсутствие страха, а победа над ним.', 'Courage is not the absence of fear, but the triumph over it.', 'Нельсон Мандела', 'confidence'),
  ('Ты смелее, чем думаешь, сильнее, чем кажешься, и умнее, чем полагаешь.', 'You are braver than you believe, stronger than you seem, and smarter than you think.', 'Алан Милн', 'confidence'),
  ('То, что позади и то, что впереди, — мелочи по сравнению с тем, что внутри нас.', 'What lies behind us and what lies before us are tiny matters compared to what lies within us.', 'Ральф Эмерсон', 'confidence'),
  ('Самое красивое, что можно носить, — уверенность.', 'The most beautiful thing you can wear is confidence.', 'Блейк Лайвли', 'confidence'),
  ('Хочешь формулу успеха? Удвойте частоту неудач.', 'Would you like me to give you a formula for success? It''s quite simple: double your rate of failure.', 'Томас Уотсон', 'confidence'),
  ('Уверенность приходит не от того, что всегда прав, а от того, что не боишься ошибаться.', 'Confidence comes not from always being right but from not fearing to be wrong.', 'Питер Макинтайр', 'confidence'),
  ('Оправдывай свои ограничения — и они станут твоими.', 'Argue for your limitations, and sure enough they''re yours.', 'Ричард Бах', 'confidence'),
  ('Всё, что разум способен представить и во что поверит, — он достигнет.', 'Whatever the mind can conceive and believe, it can achieve.', 'Наполеон Хилл', 'confidence'),
  ('Путь к уверенности — делать то, чего ты боишься.', 'The way to develop self-confidence is to do the thing you fear.', 'Уильям Брайан', 'confidence'),
  ('Ты обретаешь силу и уверенность, когда каждый раз смотришь страху в лицо.', 'You gain strength, courage, and confidence by every experience in which you really stop to look fear in the face.', 'Элеонора Рузвельт', 'confidence'),
  ('Бездействие рождает сомнение. Действие рождает уверенность и смелость.', 'Inaction breeds doubt and fear. Action breeds confidence and courage.', 'Дейл Карнеги', 'confidence'),
  ('Не жди идеального момента. Его не будет.', 'Don''t wait until everything is just right. It will never be perfect.', 'Марк Хансен', 'confidence'),
  ('Великие духи всегда встречали яростное сопротивление посредственных умов.', 'Great spirits have always encountered violent opposition from mediocre minds.', 'Альберт Эйнштейн', 'confidence'),
  ('Будь собой; все остальные роли уже заняты.', 'Be yourself; everyone else is already taken.', 'Оскар Уайльд', 'confidence'),
  ('Никогда не опускай голову. Держи её высоко и смотри миру прямо в глаза.', 'Never bend your head. Always hold it high. Look the world straight in the eye.', 'Хелен Келлер', 'confidence'),
  ('Никто не может вернуться и начать сначала, но каждый может начать сегодня и сделать новый финал.', 'Nobody can go back and start a new beginning, but anyone can start today and make a new ending.', 'Мария Робинсон', 'confidence'),
  ('Это твоё место в мире, это твоя жизнь. Иди и сделай всё, что можешь, с ней.', 'It''s your place in the world; it''s your life. Go on and do all you can with it.', 'Джимми Картер', 'confidence'),
  ('Дисциплина — это напоминание себе, чего ты на самом деле стоишь.', 'Discipline is a reminder to yourself of what you are truly worth.', 'Автор неизвестен', 'confidence')
